// packages/core/test/review-tmp/gel-robustness-f1.test.ts  ->  npx vitest run test/review-tmp/gel-robustness-f1.test.ts
import { existsSync, readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { DEFAULT_RESOLUTION, simulateLane } from '../../src/gel/lane';
import { migrate } from '../../src/gel/migration';

/** Spread (fraction of the gel) between the highest and lowest fragment of a band (linear DNA). */
const spread = (sizes: number[], agarosePercent = 1): number =>
  migrate(sizes[sizes.length - 1], { agarosePercent }) - migrate(sizes[0], { agarosePercent });

describe('gel: a band must not swallow fragments that are farther apart than the resolution', () => {
  it('BAC-sized EcoRI digest (E. coli U00096.3 1,000,000-1,150,000) on 0.8 % TAE', () => {
    const cluster = [14083, 13222, 12268, 11559, 10627, 9971]; // consecutive gaps < 0.01, ends 0.029 apart
    expect(spread(cluster, 0.8)).toBeGreaterThan(2 * DEFAULT_RESOLUTION);
    const bands = simulateLane(cluster.map((size) => ({ size })), { agarosePercent: 0.8 });
    // actual: ONE band, count 6, position 0.286, size 12,124 bp (mass-weighted mean)
    for (const b of bands) expect(spread(b.sizes, 0.8), `${b.sizes.join('/')}`).toBeLessThan(DEFAULT_RESOLUTION);
  });

  it('dense series 1000..2020 bp (30 bp steps): 1 kb and 2 kb end up in the same band', () => {
    const bands = simulateLane(Array.from({ length: 35 }, (_, i) => ({ size: 1000 + 30 * i })));
    // actual: one band at 0.533 (1570.8 bp) although migrate(1000) - migrate(2020) = 0.140
    for (const b of bands) expect(spread(b.sizes), `${b.count} fragments at ${b.position}`).toBeLessThan(DEFAULT_RESOLUTION);
  });

  const ECOLI = resolve(import.meta.dirname, '../fixtures/large/ecoli_U00096.3.gb');
  it.skipIf(!existsSync(ECOLI))('E. coli genome / EcoRI (646 fragments, as Biopython 1.88) is not a 5-band lane', () => {
    const text = readFileSync(ECOLI, 'utf8');
    const body = text.indexOf('\n', text.search(/^ORIGIN/m)) + 1;
    const seq = text.slice(body, text.indexOf('\n//', body)).replace(/[^A-Za-z]/g, '').toUpperCase();
    const n = seq.length;
    const wrapped = seq + seq.slice(0, 5);
    const cuts: number[] = [];
    for (let i = wrapped.indexOf('GAATTC'); i >= 0 && i < n; i = wrapped.indexOf('GAATTC', i + 1)) cuts.push((i + 1) % n);
    cuts.sort((a, b) => a - b);
    const fragments = cuts.map((c, k) => (cuts[(k + 1) % cuts.length] - c + n) % n || n);
    expect(fragments).toHaveLength(646);
    const bands = simulateLane(fragments.map((size) => ({ size })));
    // actual: 5 bands; bands[0] = 528 fragments 42,844..1,180 bp (positions 0.195..0.587) at ONE position 0.260,
    // size 14,895 bp, intensity 1; the other bands get intensities 0.0000-0.011
    expect(spread(bands[0].sizes), `${bands[0].count} fragments at ${bands[0].position}`).toBeLessThan(DEFAULT_RESOLUTION);
  });
});
// Oracle cross-check of the inputs: Biopython 1.88 EcoRI.search on U00096.3 (circular) -> 646 fragments, max 42844, min 14;
// EcoRI.catalyse(seq[1000000:1150000], linear=True) -> 28 fragments including 14083, 13222, 12268, 11559, 10627, 9971.

