function circularDigest(seq: string, site: string): number[] {
  const n = seq.length;
  const wrapped = seq + seq.slice(0, site.length - 1);
  const cuts: number[] = [];
  for (let i = wrapped.indexOf(site); i >= 0 && i < n; i = wrapped.indexOf(site, i + 1)) cuts.push(i);
