import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { describe, expect, it } from 'vitest';
import { DEFAULT_RESOLUTION, simulateLane } from '../../src/gel/lane';
import { migrate } from '../../src/gel/migration';
import type { GelBuffer } from '../../src/gel/migration';

// FRESH photo: Thermo GeneRuler 50 bp DNA Ladder, MAN0013016 Rev. C.00 p.2 (2.5% agarose, 1X TBE, 5 V/cm, 1 h, 8 cm gel).
// Rows = background-subtracted lane-profile peaks (parabolic refinement) of the embedded 724x915 image, lane columns 50-115.
const GR50_2_5_TBE: Array<[number, number]> = [[1000, 152.77], [900, 164.54], [800, 178.41], [700, 194.68], [600, 213.99],
  [500, 237.77], [400, 268.12], [300, 305.78], [250, 328.5], [200, 356.41], [150, 388.87], [100, 425.15], [50, 477.42]];

function affineRms(bands: Array<[number, number]>, agarosePercent: number, buffer: GelBuffer): number {
  const p = bands.map(([s]) => migrate(s, { agarosePercent, buffer }));
  const rows = bands.map(([, r]) => r);
  const n = p.length;
  const mp = p.reduce((a, b) => a + b, 0) / n;
  const mr = rows.reduce((a, b) => a + b, 0) / n;
  let sxy = 0; let sxx = 0;
  for (let i = 0; i < n; i++) { sxy += (p[i] - mp) * (rows[i] - mr); sxx += (p[i] - mp) ** 2; }
  const alpha = sxy / sxx; const beta = mr - alpha * mp;
  const span = Math.max(...rows) - Math.min(...rows);
  const res = p.map((x, i) => (alpha * x + beta - rows[i]) / span);
  return Math.sqrt(res.reduce((a, r) => a + r * r, 0) / n);
}

describe('gel science: TBE calibration at 1.7-2.5 % agarose', () => {
  it('reproduces the fresh 2.5 % TBE photo within the claimed accuracy (RMS < 0.02)', () => {
    expect(affineRms(GR50_2_5_TBE, 2.5, 'TBE')).toBeLessThan(0.02); // actual 0.0447 (TAE curve: 0.0088)
  });

  it('on every TBE photo at >= 1.7 % agarose, the TBE curve fits at least as well as the TAE curve', () => {
    const vendor = JSON.parse(readFileSync(resolve(import.meta.dirname, '../oracle/gel/vendor_gels.json'), 'utf8')) as
      { gels: Array<{ id: string; pct: number; buffer: GelBuffer; bands: Array<[number, number]> }> };
    const photos = vendor.gels.filter((g) => g.buffer === 'TBE' && g.pct >= 1.7).map((g) => ({ id: g.id, pct: g.pct, bands: g.bands }));
    photos.push({ id: 'thermo-sm0371-2.5pct-tbe (fresh)', pct: 2.5, bands: GR50_2_5_TBE });
    expect(photos.length).toBe(3);
    for (const g of photos) expect(affineRms(g.bands, g.pct, 'TBE'), g.id).toBeLessThanOrEqual(affineRms(g.bands, g.pct, 'TAE'));
  });

  it('keeps the 1000/900 bp spacing within 25 % of the photo (fraction of the 1000-50 bp span)', () => {
    const opts = { agarosePercent: 2.5, buffer: 'TBE' as GelBuffer };
    const row = new Map(GR50_2_5_TBE);
    const photo = (row.get(900)! - row.get(1000)!) / (row.get(50)! - row.get(1000)!);
    const model = (migrate(900, opts) - migrate(1000, opts)) / (migrate(50, opts) - migrate(1000, opts));
    expect(model / photo).toBeGreaterThan(0.75); // actual 0.567
  });

  it('1000 and 910 bp are resolved at the default resolution, as on the vendor gel', () => {
    const opts = { agarosePercent: 2.5, buffer: 'TBE' as GelBuffer };
    const row = new Map(GR50_2_5_TBE);
    const frac = (row.get(900)! - row.get(1000)!) / (row.get(50)! - row.get(1000)!);
    const photoSeparation = frac * (Math.log(1000 / 910) / Math.log(1000 / 900)) * (migrate(50, opts) - migrate(1000, opts));
    expect(photoSeparation).toBeGreaterThan(1.5 * DEFAULT_RESOLUTION); // passes: ~0.016
    expect(simulateLane([{ size: 1000 }, { size: 910 }], opts)).toHaveLength(2); // FAILS: 1 band (model separation 0.0093)
  });
});

